class RateLimiter:
    def __init__(self, cap, rate): self.cap = cap; self.tokens = cap; self.rate = rate; self.last = time.time()
    def allow(self):
        now = time.time()
        self.tokens = min(self.cap, self.tokens + (now - self.last) * self.rate)
        self.last = now
        if self.tokens >= 1: self.tokens -= 1; return True
        return False

